CREATE TABLE IF NOT EXISTS players (
  id serial PRIMARY KEY,
  steamid varchar(255),
  steamid64 varchar(255) UNIQUE, 
  nick varchar(255) NOT NULL,
  profileurl text,
  avatarfull text,
  avatarCustom text,
  dashboard text,
  date_joined timestamp DEFAULT current_timestamp,
  last_login_site timestamp(6) NOT NULL DEFAULT current_timestamp(6),
  last_login_server timestamp(6) NOT NULL DEFAULT current_timestamp(6),
  role text NOT NULL DEFAULT 'player' CHECK (role IN ('player', 'premium', 'admin'))
);




CREATE TABLE IF NOT EXISTS "maps" (
  "id" SERIAL PRIMARY KEY,
  "name" varchar(50) NOT NULL,
  "alternative_name" text DEFAULT NULL,
  "src" text DEFAULT NULL,
  "date_created" timestamp NOT NULL DEFAULT current_timestamp
);

    


CREATE TABLE IF NOT EXISTS "triggers" (
  "id" SERIAL NOT NULL,
  "name" varchar(255) NOT NULL,
  "alternative_name" varchar(255) DEFAULT NULL,
  "x" real DEFAULT NULL,
  "y" real DEFAULT NULL,
  "z" real DEFAULT NULL,
  "map_id" integer NOT NULL DEFAULT 0,
  "src" text DEFAULT NULL
);



CREATE TABLE IF NOT EXISTS "tricks" (
  "id" SERIAL PRIMARY KEY,
  "name" varchar(255) NOT NULL,
  "point" smallint NOT NULL,
  "velocity" smallint NOT NULL,
  "date_add" timestamp NOT NULL DEFAULT current_timestamp,
  "author_id" integer NOT NULL,
  "map_id" integer NOT NULL DEFAULT 0
);


CREATE TABLE IF NOT EXISTS "routes" (
  "id" SERIAL PRIMARY KEY,
  "trick_id" integer DEFAULT NULL,
  "trigger_id" integer DEFAULT NULL
);


CREATE TABLE IF NOT EXISTS "completes" (
  "id" SERIAL PRIMARY KEY,
  "player_id" integer DEFAULT NULL,
  "trick_id" integer DEFAULT NULL,
  "speed" smallint DEFAULT NULL,
  "time" real DEFAULT NULL,
  "date_add" timestamp DEFAULT current_timestamp
);

